import{_ as i,l,o as t,c as s,v as e,p as n,x as o,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"焦面倾斜与场曲补偿","description":"","frontmatter":{"title":"焦面倾斜与场曲补偿","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/focus-tilt-compensation.md","filePath":"litho/focus-tilt-compensation.md","lastUpdated":1789023840000}'),c={name:"litho/focus-tilt-compensation.md"};function m(E,a,_,A,B,u){const r=l("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="焦面倾斜与场曲补偿" tabindex="-1">焦面倾斜与场曲补偿 <a class="header-anchor" href="#焦面倾斜与场曲补偿" aria-label="Permalink to &quot;焦面倾斜与场曲补偿&quot;">​</a></h1><div class="epigraph"><p>最佳焦面若在场上是斜的或弯的，调焦闭环对不准每一个场点；补偿是把可驱动的 $Z_4$ 与调平去贴那张面，不是改 NA。</p><footer>—— 场曲与倾斜的车间语言见 Malacara；光刻调平与离焦见 Levinson、Mack</footer></div><p><a href="/litho/aberration-nils-sensitivity">上一课</a>把 \\(c_j\\) 接到了 NILS。缺口是：视场上最佳焦面并不平——<strong>倾斜</strong>与<strong>场曲</strong>让狭缝两端和场角的有效离焦不同，敏感度再高也救不了没补偿的几何。本课钉这两项及其补偿，结束「成像的数学骨架」课序。二维孔与线端留给下一课序。不重推 \\(\\mathrm{DOF}=k_2\\lambda/\\mathrm{NA}^2\\) 的公式，只引用<a href="/litho/defocus-as-aberration">离焦作为像差</a>的 \\(Z_4\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>初级场曲（Petzval 一类）让离轴点的最佳焦面弯离近轴焦面；倾斜让整个焦面相对晶圆法向有一楔。扫描狭缝沿 \\(x\\) 瞬时曝光一条带，带上各点若 \\(c_4\\) 不同，NILS\\((z)\\) 的窗口对不齐，一层的公共焦窗按最差场点关死。调平传感器看到的是晶圆形貌，镜头场曲是光学面；两者差才是残差离焦。</p><p>缺口不是再写一次二次相位，而是：哪些项可以用工件台调平、扫描同步和镜头补偿吃掉，哪些必须当残差进预算。把场曲写成「晶圆不平」，会去拧涂胶；把晶圆翘曲写成「场曲」，会去拧镜头。</p><h3 id="倾斜不是远心" tabindex="-1">倾斜不是远心 <a class="header-anchor" href="#倾斜不是远心" aria-label="Permalink to &quot;倾斜不是远心&quot;">​</a></h3><p>远心误差是主光线斜率，造成套刻随离焦走，见主干远心课。焦面倾斜是 \\(z\\) 沿场线性变，造成 CD / NILS 沿场变。可以同时存在：一台机既可以远心残差，又可以焦面楔。敏感度上一课已经分开奇偶；本课的倾斜主要吃偶项里的有效 \\(z\\)。</p><p><span class="marginnote">扫描方向再平均一次：瞬时倾斜在狭缝宽度上积分。补偿表必须按狭缝坐标建，不能只用场中心的 Bossung。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：通过焦点的 CD 或 NILS 在狭缝若干点扫 \\(z\\)，拟合每点的最佳焦，得到一张 \\(z_\\mathrm{best}(x,y)\\)。分解成活塞（全局调焦）、倾斜（两轴楔）、弯曲（场曲残差）。晶圆形貌用调平光束另测，相减后才是光学场曲。</p><p>补偿：全局 \\(z\\) 跟活塞；工件台或镜头执行器跟楔；剩余弯曲进预算或靠镜头加热/补偿光学（公开可写的是「场相关调焦」，不写未公开行程）。浸没层水膜厚度误差也会冒充倾斜，要与光学项拆开。</p>',12)),(t(),n(d,null,{default:o(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22z_best%20%E5%9C%BA%E5%9B%BE%22%5D%20--%3E%20PIS%5B%22%E6%B4%BB%E5%A1%9E%20%E2%86%92%20%E8%B0%83%E7%84%A6%22%5D%0A%20%20MAP%20--%3E%20TIL%5B%22%E5%80%BE%E6%96%9C%20%E2%86%92%20%E8%B0%83%E5%B9%B3%20%2F%20%E6%89%A7%E8%A1%8C%E5%99%A8%22%5D%0A%20%20MAP%20--%3E%20CURV%5B%22%E5%9C%BA%E6%9B%B2%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20WAF%5B%22%E6%99%B6%E5%9C%86%E5%BD%A2%E8%B2%8C%22%5D%20--%3E%20LEV%5B%22%E8%B0%83%E5%B9%B3%22%5D%0A%20%20CURV%20--%3E%20BUD%5B%22%E7%84%A6%E7%AA%97%E9%A2%84%E7%AE%97%22%5D%0A%20%20LEV%20--%3E%20BUD%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="与畸变、像散的协作" tabindex="-1">与畸变、像散的协作 <a class="header-anchor" href="#与畸变、像散的协作" aria-label="Permalink to &quot;与畸变、像散的协作&quot;">​</a></h3><p>像散把 H/V 最佳焦劈开，场曲对两种取向不是同一张面。补偿若只贴一种取向的 \\(z_\\mathrm{best}\\)，另一种的 NILS 会掉——上一课敏感度在这里变成场上的取向冲突。畸变是横向位移，不靠调焦消除；不要把网格校正和焦面补偿写成一个环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个场点的有效离焦 \\(z-z_\\mathrm{best}\\) 乘上一课的 \\(\\partial\\mathrm{NILS}/\\partial z\\)（即对 \\(c_4\\) 的敏感度），得到场上 NILS 地图。公共工艺窗是地图的交集。补偿降低的是这张地图的峰峰值，不是改变 \\(\\mathrm{NA}\\)。扫描同步若在狭缝方向留下动态倾斜，等效于补偿环没跟上的楔，CD 沿扫描向拖尾。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写未公开的调平激光路数或镜头补偿器规格。EUV 反射系统同样有场曲，只是光路折叠不同，定义仍是 \\(z_\\mathrm{best}\\) 面。胶厚与薄膜摆动也会让「最佳焦」随栈变，那是下一单元的反射问题，不要在本课用 BARC 冒充场曲补偿。</p><p>至此，傅里叶对 → 采样 → PSF → 传递函数 → 判据 → Abbe/Hopkins → SOCS → 相干 → speckle → 矢量 → 像差敏感度 → 场焦补偿，骨架课序结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>场曲与倾斜使 \\(z_\\mathrm{best}\\) 随场变，公共焦窗按最差点关。</li><li>形貌归调平，光学面归镜头/执行器，残差进预算。</li><li>倾斜不是远心；像散让 H/V 焦面分裂。</li><li>补偿贴的是 NILS 地图的平坦度，不改截止频率。</li><li>下一课序：把骨架用到接触孔与线端。</li><li>出处：Malacara；Levinson；Mack；离焦 \\(Z_4\\) 见主干离焦课。</li></ul>',9))])}const S=i(c,[["render",m]]);export{f as __pageData,S as default};
